    { "id": "bp69", "story": "Zavod yaqinidagi o'rmon daraxtlarida avval uchraydigan lishaynik (moxsimon o'simlik) lar butunlay yo'qolib ketdi. Ammo barglar joyida turibdi.", "question": "Buning sababi nima bo'lishi mumkin?", "options": ["Yomg'ir yog'magani", "Zavod tutunidan havo kuchli ifloslangani. Lishayniklar eng kuchli bioindikator bo'lib, faqat top-toza havoda yashaydi", "Qushlar yeb qo'ygani"], "answer_index": 1, "explanation": "To'g'ri! Lishayniklarning yo'qolishi havodagi oltingugurt dioksidi (SO2) kabi zaharlar ortganini bildiradi." },
    { "id": "bp70", "story": "Uy qurilishi munosabati bilan bog'dagi eski, ichi kovak daraxtni kesib tashlashdi. Tez orada bog'ni zararkunandalar bosdi.", "question": "Qanday aloqasi bor?", "options": ["Daraxtning kasali tarqaldi", "Eski kovak daraxtda boyo'g'li va ko'rshapalaklar yashardi. Ular kesilgach zararkunandalarni yeydigan jonzot qolmadi", "Hech qanday aloqasi yo'q"], "answer_index": 1, "explanation": "To'g'ri! Kovakli daraxtlar tunda ov qiluvchi foydali qushlar va ko'rshapalaklar uchun bebaho uydir." },
