    { "id": "bp74", "story": "Olimlar qutb ayiqlarining qonidan Antarktidada umuman ishlatilmaydigan pestisidlar (qishloq xo'jaligi zaharlari) qoldig'ini topishdi.", "question": "Qanday qilib zahar qutbga yetib bordi?", "options": ["Sayyohlar olib borgan", "Pestisidlar daryolar orqali okeanga tushib, planktonlarga, so'ngra baliqlarga, tyulenlarga, oxiri ularni yegan oq ayiqlarga (biologik yig'ilish) o'tgan", "Qutbda ham dehqonchilik qilingan"], "answer_index": 1, "explanation": "To'g'ri! Biomagnifikatsiya jarayoni orqali zaharlar oziq zanjirining eng cho'qqisida turgan hayvonlarga minglab barobar kuchliroq bo'lib yetib boradi." },
    { "id": "bp75", "story": "O'zbekistonda lalmi (suvsiz) tog' yonbag'irlariga ko'plab bodom va pista daraxtlari ekila boshlandi.", "question": "Bu ekologiya uchun qanday foyda beradi?", "options": ["Faqat hosil olinadi", "Qurg'oqchilikka chidamli daraxtlar tuproq eroziyasini (sel va ko'chkilar) oldini oladi, hamda tog'larni yashillashtiradi", "Zarar keltiradi"], "answer_index": 1, "explanation": "To'g'ri! Tog' yonbag'irlarida o'rmon (bog') barpo etish tuproq yemirilishining (eroziyasining) eng yaxshi tabiiy davosidir." },
    { "id": "bp76", "story": "Zavod tutunini tozalovchi filtrlarni faqat tekshiruvchilar kelganda yoqib, tunda esa o'chirib qo'yishni odat qildi.", "question": "Bunday holatning atrofga yashirin xavfi nimada?", "options": ["Pul tejaladi", "Zaharli gazlar ayniqsa tunda inyersiya (havo bosimi tushishi) sababli yerga yaqinroq cho'kadi va uxlab yotgan aholining qattiq zaharlanishiga sabab bo'ladi", "Tunda zarar qilmaydi"], "answer_index": 1, "explanation": "To'g'ri! Tunda shamol pasayib, harorat tushgani uchun zaharli gazlar osmonga ko'tarilmay, to'g'ridan-to'g'ri odamlar yashaydigan qatlamga yoyiladi." },
    { "id": "bp77", "story": "Dehqon dalasida ekinlarga kimyoviy dori sepdi, lekin shu kuni qattiq shamol turdi.", "question": "Bu vaziyat qanday fojia keltirib chiqaradi?", "options": ["Dori uchib ketib yo'qoladi", "Shamol zaharni qo'shni qishloqlarga, suv havzalariga va yaylovlarga uchirib, u yerdagi o'simliklar, asalarilar va odamlarni zaharlaydi", "Shamol dorini kuchaytiradi"], "answer_index": 1, "explanation": "To'g'ri! Shamolli havoda zahar sepish xavfsizlik qoidalarini qo'pol ravishda buzish hisoblanib, ulkan zararlar (drift) keltiradi." },
    { "id": "bp78", "story": "Uy hayvonlari sifatida ko'p boqiladigan sigirlarning oshqozon faoliyati (kavsh qaytarishi) ekologlar tomonidan muammo deb e'lon qilindi.", "question": "Sababi nima?", "options": ["Go'shti kamaygani", "Sigirlar hazm qilish jarayonida havoga millionlab tonna Metan gazi ajratadi. Metan CO2 dan 25 barobar kuchli issiqxona gazidir", "Ko'p o't yeyishi"], "answer_index": 1, "explanation": "To'g'ri! Global isishning qariyb 14.5% i aynan chorvachilik, xususan qoramollar ajratadigan metan hissasiga to'g'ri keladi." },
    { "id": "bp79", "story": "Qishloqdagi yagona katta ko'l yoz faslida butunlay qurib qoldi. Lekin yomg'ir suvi bilan emas, undagi suv buloqdan kelardi.", "question": "Buloq nega quridi?", "options": ["Quyosh juda isib ketdi", "Yaqin atrofdagi dehqonlar yer ostidan suv so'ruvchi artezian quduqlarini haddan tashqari ko'p qazishgani uchun sizot suvlari sathi tushib ketdi", "Buloq qariydi"], "answer_index": 1, "explanation": "To'g'ri! Yer osti suvlaridan nazoratsiz foydalanish yer ustidagi buloq va ko'llarning qurishining asosiy sababidir." },
    { "id": "bp80", "story": "Yoshlar tog'da dam olib, ketish oldidan barcha plastik va qog'oz chiqindilarni bir joyga to'plab chuqurga ko'mib ketishdi.", "question": "Ular tabiatga yaxshilik qildimi?", "options": ["Ha, joy toza bo'ldi", "Yo'q, plastiklar yer ostida yuzlab yillar chirimay yotadi va yomg'ir yordamida tuproq va yer osti suvlarini zaharlashda davom etadi. Ularni shahar axlatxonasiga olib ketish kerak edi", "Plastik o'g'it bo'ladi"], "answer_index": 1, "explanation": "To'g'ri! Tabiat qo'ynida hech qanday chiqindini (ayniqsa sun'iy) ko'mib qoldirish mumkin emas. Ular yig'ilib maxsus zavodga ketishi shart." }
